templates.template:
ActivityDiagram ${name}
has activities {
	Activity ${firstActivity} {
		description : "${what_it_does}"
		requireCapability : ${capability}
		time : 30.0 secs
	}
}${cursor}

Activity ${name} {
	description : "${what_it_does}"
	requireCapability : ${capability}
	nextActivity : ${next}
	time : 30.0 secs
}${cursor}

Activity ${name} {
	description : "${what_it_does}"
	requireCapability : ${capability}
	conditions {
		from ${outcome} => nextActivity : ${next}
	}
}${cursor}
